cd /workspace && head -c 200 tmp/scale_full.out; echo; python3 -c "
import sys,json; sys.path.insert(0,'/workspace/submission')
from protocol import parse_request, Invalid
import fib
for f in ['tmp/scale_full.json','tmp/scale_maxroutes.json']:
    try:
        cases=parse_request(open(f).read().encode())
    except Invalid as e:
        print(f,'PARSE INVALID',e); continue
    tot=0
    for c in cases:
        vs=fib.publish(c['initial'],c['transactions'])
        rs=[len(s) for s,_ in vs]; tot+=sum(rs)
        print(f,'R',rs[:8],'total',tot, 'rows',len(c['initial'])+sum(len(t) for t in c['transactions']), 'entries',sum(len(vs[i][0]) for i in range(len(vs))))
"
